 1→/**
 2→ * Kysely migration runner.
 3→ *
 4→ * Usage:
 5→ *   npx tsx scripts/migrate.ts              # migrate to latest
 6→ *   npx tsx scripts/migrate.ts --down       # rollback last migration
 7→ *
 8→ * Reads DATABASE_URL from the environment (defaults to local Docker MySQL).
 9→ */
10→
11→import { promises as fs } from "node:fs";
12→import * as path from "node:path";
13→import {
14→  FileMigrationProvider,
15→  Kysely,
16→  Migrator,
17→  MysqlDialect,
18→} from "kysely";
19→import { createPool } from "mysql2";
20→
21→const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
22→const parsed = new URL(url);
23→
24→const isLocalhost =
25→  parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";
26→
27→const db = new Kysely<unknown>({
28→  dialect: new MysqlDialect({
29→    pool: createPool({
30→      host: parsed.hostname,
31→      port: Number(parsed.port) || 3306,
32→      user: decodeURIComponent(parsed.username),
33→      password: decodeURIComponent(parsed.password),
34→      database: parsed.pathname.replace("/", ""),
35→      // PlanetScale requires TLS; skip for local Docker MySQL
36→      ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
37→    }),
38→  }),
39→});
40→
41→const migrator = new Migrator({
42→  db,
43→  provider: new FileMigrationProvider({
44→    fs,
45→    path,
46→    migrationFolder: path.resolve(import.meta.dirname, "../db/migrations"),
47→  }),
48→});
49→
50→async function main() {
51→  const direction = process.argv.includes("--down") ? "down" : "up";
52→
53→  const { error, results } =
54→    direction === "down"
55→      ? await migrator.migrateDown()
56→      : await migrator.migrateToLatest();
57→
58→  results?.forEach((it) => {
59→    if (it.status === "Success") {
60→      console.log(`  ${it.direction === "Up" ? "↑" : "↓"} ${it.migrationName}`);
61→    } else if (it.status === "Error") {
62→      console.error(`  ✗ ${it.migrationName}`);
63→    }
64→  });
65→
66→  if (error) {
67→    console.error("Migration failed:");
68→    console.error(error);
69→    await db.destroy();
70→    process.exit(1);
71→  }
72→
73→  if (!results?.length) {
74→    console.log("No migrations to run — already up to date.");
75→  }
76→
77→  await db.destroy();
78→}
79→
80→main();
