/**
 * Backfill script: Index checkpoints into Turbopuffer for full-text + semantic search.
 *
 * Usage:
 *   npx tsx scripts/backfill-search.ts [options]
 *
 * Options:
 *   --repo <full_name>     Only backfill a specific repo (e.g., "entireio/cli")
 *   --with-transcripts     Fetch transcript excerpts from GitHub (slower, needs GITHUB_TOKEN)
 *   --dry-run              Show what would be indexed without writing to Turbopuffer
 *   --limit <n>            Max checkpoints per repo (for testing)
 *
 * Environment:
 *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 *   GITHUB_TOKEN           GitHub PAT with repo read access (required for --with-transcripts)
 */

import { Kysely, MysqlDialect } from "kysely";
import { createPool } from "mysql2";
import type { DB } from "../db/types";
import Turbopuffer from "@turbopuffer/turbopuffer";
import OpenAI from "openai";
import { getParserForAgent } from "../src/lib/transcript-parsers/registry";

// --- Config ---

const EMBEDDING_MODEL = "text-embedding-3-small";
const EMBEDDING_DIMENSIONS = 1536;
const EMBEDDING_BATCH_SIZE = 50;
const TURBOPUFFER_UPSERT_BATCH_SIZE = 50;
const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
const GITHUB_API = "https://api.github.com";
const TRANSCRIPT_DELAY_MS = 200; // delay between GitHub API calls to avoid rate limiting
const MAX_TRANSCRIPT_CHARS = 2000;

// --- CLI Argument Parsing ---

interface CliOptions {
  repo: string | null;
  withTranscripts: boolean;
  dryRun: boolean;
  limit: number | null;
}

function parseArgs(): CliOptions {
  const args = process.argv.slice(2);
  const options: CliOptions = {
    repo: null,
    withTranscripts: false,
    dryRun: false,
    limit: null,
  };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case "--repo":
        options.repo = args[++i];
        if (!options.repo) {
          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
          process.exit(1);
        }
        break;
      case "--with-transcripts":
        options.withTranscripts = true;
        break;
      case "--dry-run":
        options.dryRun = true;
        break;
      case "--limit":
        options.limit = parseInt(args[++i], 10);
        if (isNaN(options.limit) || options.limit <= 0) {
          console.error("Error: --limit requires a positive integer");
          process.exit(1);
        }
        break;
      default:
        console.error(`Unknown option: ${args[i]}`);
        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
        process.exit(1);
    }
  }

  return options;
}

// --- Database Setup ---

function createDb(): Kysely<DB> {
  const url = process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
  const parsed = new URL(url);
  const isLocalhost = parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1";

  return new Kysely<DB>({
    dialect: new MysqlDialect({
      pool: createPool({
        host: parsed.hostname,
        port: Number(parsed.port) || 3306,
        user: decodeURIComponent(parsed.username),
        password: decodeURIComponent(parsed.password),
        database: parsed.pathname.replace("/", ""),
        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
      }),
    }),
  });
}

// --- Text Construction ---

function buildSearchText(
  checkpoint: CheckpointRow,
  transcriptExcerpt?: string,
): string {
  const parts: string[] = [];

  if (checkpoint.prompt) {
    parts.push(`Prompt: ${checkpoint.prompt}`);
  }
  if (checkpoint.commit_message) {
    parts.push(`Commit: ${checkpoint.commit_message}`);
  }
  if (checkpoint.files_touched_str) {
    parts.push(`Files: ${checkpoint.files_touched_str}`);
  }
  if (transcriptExcerpt) {
    parts.push(`Transcript: ${transcriptExcerpt}`);
  }

  return parts.join("\n");
}

// --- Embedding Generation ---

async function generateEmbeddings(
  openai: OpenAI,
  texts: string[],
): Promise<number[][]> {
  const response = await openai.embeddings.create({
    model: EMBEDDING_MODEL,
    input: texts,
    dimensions: EMBEDDING_DIMENSIONS,
  });

  // Sort by index to maintain order
  return response.data
    .sort((a, b) => a.index - b.index)
    .map((item) => item.embedding);
}

// --- Transcript Fetching ---

async function fetchTranscriptExcerpt(
  repoFullName: string,
  checkpointId: string,
  agent: string,
  token: string,
): Promise<string | null> {
  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
  const path = `${folder}/0/full.jsonl`;

  // Encode each path segment individually (preserves / separators)
  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;

  const response = await fetch(url, {
    headers: {
      Accept: "application/vnd.github.raw+json",
      Authorization: `Bearer ${token}`,
      "User-Agent": "entire-backfill",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  });

  if (!response.ok) {
    if (response.status === 404) {
      return null;
    }
    console.warn(`  Warning: Failed to fetch transcript for ${checkpointId}: ${response.status}`);
    return null;
  }

  const content = await response.text();

  try {
    const parser = getParserForAgent(agent);
    const result = parser.parse(content);

    if (result.messages.length === 0) {
      return null;
    }

    // Extract first user message + first assistant message
    const parts: string[] = [];
    let charsUsed = 0;

    for (const msg of result.messages) {
      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;

      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
      const text = msg.content.slice(0, remaining);
      parts.push(`[${msg.role}]: ${text}`);
      charsUsed += text.length;

      // Only take the first user + first assistant
      if (msg.role === "assistant") break;
    }

    return parts.join("\n") || null;
  } catch {
    console.warn(`  Warning: Failed to parse transcript for ${checkpointId}`);
    return null;
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// --- Types ---

interface CheckpointRow {
  checkpoint_id: string;
  branch: string;
  agent: string;
  commit_author_username: string | null;
  created_at: string | null;
  commit_sha: string | null;
  commit_message: string | null;
  prompt: string | null;
  files_touched_str: string | null;
}

interface RepoRow {
  id: string;
  full_name: string;
  checkpoint_count: number;
}

// --- Per-Repo Processing ---

async function fetchCheckpointsForRepo(
  db: Kysely<DB>,
  repoId: string,
  limit: number | null,
): Promise<CheckpointRow[]> {
  // Use the same deferred-join pattern as getCheckpointsForBranch
  let idQuery = db
    .selectFrom("repo_checkpoint_commits")
    .select("id")
    .where("repo_id", "=", repoId)
    .orderBy("commit_date", "desc");

  if (limit) {
    idQuery = idQuery.limit(limit);
  }

  const idRows = await idQuery.execute();
  if (idRows.length === 0) return [];

  const rows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .leftJoin("repo_checkpoints as cp", (join) =>
      join
        .onRef("cp.repo_id", "=", "cc.repo_id")
        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
    )
    .select([
      "cc.checkpoint_id",
      "cc.branch",
      "cc.commit_sha",
      "cc.commit_message",
      "cc.commit_author_username",
      "cc.commit_date",
      "cp.prompt",
      "cp.agent",
      "cp.created_at",
      "cp.files_touched",
    ])
    .where(
      "cc.id",
      "in",
      idRows.map((r) => r.id),
    )
    .execute();

  // Restore sort order
  const rowById = new Map(rows.map((r) => [r.checkpoint_id, r]));

  return rows.map((row) => {
    const filesTouched = row.files_touched as string[] | null;
    return {
      checkpoint_id: row.checkpoint_id,
      branch: row.branch,
      agent: row.agent ?? "Claude Code",
      commit_author_username: row.commit_author_username,
      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
      commit_sha: row.commit_sha,
      commit_message: row.commit_message,
      prompt: row.prompt,
      files_touched_str: filesTouched?.join(", ") ?? null,
    };
  });
}

async function processRepo(
  db: Kysely<DB>,
  tpuf: Turbopuffer,
  openai: OpenAI,
  repo: RepoRow,
  options: CliOptions,
): Promise<{ indexed: number; skipped: number }> {
  const start = Date.now();
  console.log(`\nProcessing ${repo.full_name} (${repo.checkpoint_count} checkpoints)...`);

  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
  if (checkpoints.length === 0) {
    console.log(`  No checkpoint commits found, skipping.`);
    return { indexed: 0, skipped: 0 };
  }

  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);

  const githubToken = process.env.GITHUB_TOKEN;

  // Build text fields (with optional transcript excerpts)
  const texts: string[] = [];
  let skipped = 0;

  for (let i = 0; i < checkpoints.length; i++) {
    const cp = checkpoints[i];
    let transcriptExcerpt: string | undefined;

    if (options.withTranscripts && githubToken) {
      transcriptExcerpt =
        (await fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken)) ??
        undefined;
      // Rate limit GitHub API calls
      if (i < checkpoints.length - 1) {
        await sleep(TRANSCRIPT_DELAY_MS);
      }
    }

    const text = buildSearchText(cp, transcriptExcerpt);
    if (!text.trim()) {
      skipped++;
      texts.push(""); // placeholder to maintain index alignment
      continue;
    }

    texts.push(text);
  }

  // Filter out empty texts for embedding, but keep index mapping
  const nonEmptyIndices = texts.map((t, i) => (t.trim() ? i : -1)).filter((i) => i >= 0);
  const nonEmptyTexts = nonEmptyIndices.map((i) => texts[i]);

  if (nonEmptyTexts.length === 0) {
    console.log(`  All checkpoints had empty text, skipping.`);
    return { indexed: 0, skipped };
  }

  if (options.dryRun) {
    console.log(`  [DRY RUN] Would index ${nonEmptyTexts.length} checkpoints.`);
    for (let i = 0; i < Math.min(3, nonEmptyTexts.length); i++) {
      const idx = nonEmptyIndices[i];
      const cp = checkpoints[idx];
      console.log(`    - ${cp.checkpoint_id}: ${nonEmptyTexts[i].slice(0, 120)}...`);
    }
    return { indexed: nonEmptyTexts.length, skipped };
  }

  // Generate embeddings in batches
  console.log(`  Generating embeddings for ${nonEmptyTexts.length} checkpoints...`);
  const allEmbeddings: number[][] = [];

  for (let i = 0; i < nonEmptyTexts.length; i += EMBEDDING_BATCH_SIZE) {
    const batch = nonEmptyTexts.slice(i, i + EMBEDDING_BATCH_SIZE);
    const embeddings = await generateEmbeddings(openai, batch);
    allEmbeddings.push(...embeddings);

    if (i + EMBEDDING_BATCH_SIZE < nonEmptyTexts.length) {
      console.log(`    Embedded ${Math.min(i + EMBEDDING_BATCH_SIZE, nonEmptyTexts.length)}/${nonEmptyTexts.length}`);
    }
  }

  // Upsert to Turbopuffer in batches
  const ns = tpuf.namespace(`checkpoints-${repo.id}`);
  console.log(`  Upserting to Turbopuffer namespace checkpoints-${repo.id}...`);

  for (let i = 0; i < nonEmptyIndices.length; i += TURBOPUFFER_UPSERT_BATCH_SIZE) {
    const batchIndices = nonEmptyIndices.slice(i, i + TURBOPUFFER_UPSERT_BATCH_SIZE);
    const batchEmbeddings = allEmbeddings.slice(i, i + TURBOPUFFER_UPSERT_BATCH_SIZE);

    const ids: number[] = [];
    const vectors: number[][] = [];
    const attributes: Record<string, (string | null)[]> = {
      checkpoint_id: [],
      branch: [],
      agent: [],
      author: [],
      created_at: [],
      commit_sha: [],
      commit_message: [],
      prompt: [],
      files_touched: [],
      text: [],
    };

    for (let j = 0; j < batchIndices.length; j++) {
      const cpIdx = batchIndices[j];
      const cp = checkpoints[cpIdx];

      ids.push(i + j + 1); // 1-based auto-incrementing ID within namespace
      vectors.push(batchEmbeddings[j]);
      (attributes.checkpoint_id as (string | null)[]).push(cp.checkpoint_id);
      (attributes.branch as (string | null)[]).push(cp.branch);
      (attributes.agent as (string | null)[]).push(cp.agent);
      (attributes.author as (string | null)[]).push(cp.commit_author_username);
      (attributes.created_at as (string | null)[]).push(cp.created_at);
      (attributes.commit_sha as (string | null)[]).push(cp.commit_sha);
      (attributes.commit_message as (string | null)[]).push(cp.commit_message);
      (attributes.prompt as (string | null)[]).push(cp.prompt);
      (attributes.files_touched as (string | null)[]).push(cp.files_touched_str);
      (attributes.text as (string | null)[]).push(nonEmptyTexts[nonEmptyIndices.indexOf(cpIdx)]);
    }

    await ns.upsert({
      ids,
      vectors,
      attributes,
    });

    if (i + TURBOPUFFER_UPSERT_BATCH_SIZE < nonEmptyIndices.length) {
      console.log(`    Upserted ${Math.min(i + TURBOPUFFER_UPSERT_BATCH_SIZE, nonEmptyIndices.length)}/${nonEmptyIndices.length}`);
    }
  }

  const elapsed = ((Date.now() - start) / 1000).toFixed(1);
  console.log(`  Done: ${nonEmptyIndices.length} indexed, ${skipped} skipped (${elapsed}s)`);

  return { indexed: nonEmptyIndices.length, skipped };
}

// --- Main ---

async function main() {
  const options = parseArgs();

  // Validate env vars
  if (!options.dryRun) {
    if (!process.env.TURBOPUFFER_API_KEY) {
      console.error("Error: TURBOPUFFER_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
    if (!process.env.OPENAI_API_KEY) {
      console.error("Error: OPENAI_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
  }

  if (options.withTranscripts && !process.env.GITHUB_TOKEN) {
    console.error("Error: GITHUB_TOKEN is required when using --with-transcripts");
    process.exit(1);
  }

  const db = createDb();

  const tpuf = new Turbopuffer({
    apiKey: process.env.TURBOPUFFER_API_KEY ?? "",
  });

  const openai = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY ?? "",
  });

  console.log("Backfill Search Index");
  console.log("=====================");
  if (options.dryRun) console.log("[DRY RUN MODE]");
  if (options.repo) console.log(`Repo filter: ${options.repo}`);
  if (options.limit) console.log(`Limit: ${options.limit} checkpoints per repo`);
  if (options.withTranscripts) console.log("Transcript fetching: enabled");

  // Fetch repos with checkpoints
  let repoQuery = db
    .selectFrom("repos")
    .select(["id", "full_name", "checkpoint_count"])
    .where("checkpoint_count", ">", 0);

  if (options.repo) {
    repoQuery = repoQuery.where("full_name", "=", options.repo);
  }

  const repos = (await repoQuery.execute()) as RepoRow[];

  if (repos.length === 0) {
    console.log("\nNo repos with checkpoints found.");
    await db.destroy();
    return;
  }

  console.log(`\nFound ${repos.length} repo(s) with checkpoints.`);

  // Process each repo
  let totalIndexed = 0;
  let totalSkipped = 0;

  for (const repo of repos) {
    try {
      const result = await processRepo(db, tpuf, openai, repo, options);
      totalIndexed += result.indexed;
      totalSkipped += result.skipped;
    } catch (err) {
      console.error(`\nError processing ${repo.full_name}:`, err);
      console.error("Continuing with next repo...");
    }
  }

  // Summary
  console.log("\n=====================");
  console.log("Summary:");
  console.log(`  Repos processed: ${repos.length}`);
  console.log(`  Checkpoints indexed: ${totalIndexed}`);
  console.log(`  Checkpoints skipped: ${totalSkipped}`);

  await db.destroy();
}

main();

