112→function buildSearchText(
113→  checkpoint: CheckpointRow,
114→  transcriptExcerpt?: string,
115→): string {
116→  const parts: string[] = [];
117→
118→  if (checkpoint.prompt) {
119→    parts.push(`Prompt: ${checkpoint.prompt}`);
120→  }
121→  if (checkpoint.commit_message) {
122→    parts.push(`Commit: ${checkpoint.commit_message}`);
123→  }
124→  if (checkpoint.files_touched_str) {
125→    parts.push(`Files: ${checkpoint.files_touched_str}`);
126→  }
127→  if (transcriptExcerpt) {
128→    parts.push(`Transcript: ${transcriptExcerpt}`);
129→  }
130→
131→  return parts.join("\n");
132→}
