134→// --- Embedding Generation ---
135→
136→async function generateEmbeddings(
137→  openai: OpenAI,
138→  texts: string[],
139→): Promise<number[][]> {
140→  const response = await openai.embeddings.create({
141→    model: EMBEDDING_MODEL,
142→    input: texts,
143→    dimensions: EMBEDDING_DIMENSIONS,
144→  });
145→
146→  // Sort by index to maintain order
147→  return response.data
148→    .sort((a, b) => a.index - b.index)
149→    .map((item) => item.embedding);
150→}
