152→// --- Transcript Fetching ---
153→
154→async function fetchTranscriptExcerpt(
155→  repoFullName: string,
156→  checkpointId: string,
157→  agent: string,
158→  token: string,
159→): Promise<string | null> {
160→  const folder = `${checkpointId.slice(0, 2)}/${checkpointId.slice(2)}`;
161→  const path = `${folder}/0/full.jsonl`;
162→
163→  // Encode each path segment individually (preserves / separators)
164→  const encodedPath = path.split("/").map(encodeURIComponent).join("/");
165→  const url = `${GITHUB_API}/repos/${repoFullName}/contents/${encodedPath}?ref=${CHECKPOINT_BRANCH}`;
166→
167→  const response = await fetch(url, {
168→    headers: {
169→      Accept: "application/vnd.github.raw+json",
170→      Authorization: `Bearer ${token}`,
171→      "User-Agent": "entire-backfill",
172→      "X-GitHub-Api-Version": "2022-11-28",
173→    },
174→  });
175→
176→  if (!response.ok) {
177→    if (response.status === 404) {
178→      return null;
179→    }
180→    console.warn(`  Warning: Failed to fetch transcript for ${checkpointId}: ${response.status}`);
181→    return null;
182→  }
183→
184→  const content = await response.text();
185→
186→  try {
187→    const parser = getParserForAgent(agent);
188→    const result = parser.parse(content);
189→
190→    if (result.messages.length === 0) {
191→      return null;
192→    }
193→
194→    // Extract first user message + first assistant message
195→    const parts: string[] = [];
196→    let charsUsed = 0;
197→
198→    for (const msg of result.messages) {
199→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
200→
201→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
202→      const text = msg.content.slice(0, remaining);
203→      parts.push(`[${msg.role}]: ${text}`);
204→      charsUsed += text.length;
205→
206→      // Only take the first user + first assistant
207→      if (msg.role === "assistant") break;
208→    }
209→
210→    return parts.join("\n") || null;
211→  } catch {
212→    console.warn(`  Warning: Failed to parse transcript for ${checkpointId}`);
213→    return null;
214→  }
215→}
