221→// --- Types ---
222→
223→interface CheckpointRow {
224→  checkpoint_id: string;
225→  branch: string;
226→  agent: string;
227→  commit_author_username: string | null;
228→  created_at: string | null;
229→  commit_sha: string | null;
230→  commit_message: string | null;
231→  prompt: string | null;
232→  files_touched_str: string | null;
233→}
234→
235→interface RepoRow {
236→  id: string;
237→  full_name: string;
238→  checkpoint_count: number;
239→}
240→
241→// --- Per-Repo Processing ---
242→
243→async function fetchCheckpointsForRepo(
244→  db: Kysely<DB>,
245→  repoId: string,
246→  limit: number | null,
247→): Promise<CheckpointRow[]> {
248→  // Use the same deferred-join pattern as getCheckpointsForBranch
249→  let idQuery = db
250→    .selectFrom("repo_checkpoint_commits")
251→    .select("id")
252→    .where("repo_id", "=", repoId)
253→    .orderBy("commit_date", "desc");
254→
255→  if (limit) {
256→    idQuery = idQuery.limit(limit);
257→  }
258→
259→  const idRows = await idQuery.execute();
260→  if (idRows.length === 0) return [];
261→
262→  const rows = await db
263→    .selectFrom("repo_checkpoint_commits as cc")
264→    .leftJoin("repo_checkpoints as cp", (join) =>
265→      join
266→        .onRef("cp.repo_id", "=", "cc.repo_id")
267→        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
268→    )
269→    .select([
270→      "cc.checkpoint_id",
271→      "cc.branch",
272→      "cc.commit_sha",
273→      "cc.commit_message",
274→      "cc.commit_author_username",
275→      "cc.commit_date",
276→      "cp.prompt",
277→      "cp.agent",
278→      "cp.created_at",
279→      "cp.files_touched",
280→    ])
281→    .where(
282→      "cc.id",
283→      "in",
284→      idRows.map((r) => r.id),
285→    )
286→    .execute();
287→
288→  return rows.map((row) => {
289→    const filesTouched = row.files_touched as string[] | null;
290→    return {
291→      checkpoint_id: row.checkpoint_id,
292→      branch: row.branch,
293→      agent: row.agent ?? "Claude Code",
294→      commit_author_username: row.commit_author_username,
295→      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
296→      commit_sha: row.commit_sha,
297→      commit_message: row.commit_message,
298→      prompt: row.prompt,
299→      files_touched_str: filesTouched?.join(", ") ?? null,
300→    };
301→  });
302→}
303→
304→async function processRepo(
305→  db: Kysely<DB>,
306→  tpuf: Turbopuffer,
307→  openai: OpenAI,
308→  repo: RepoRow,
309→  options: CliOptions,
310→): Promise<{ indexed: number; skipped: number }> {
311→  const start = Date.now();
312→  console.log(`\nProcessing ${repo.full_name} (${repo.checkpoint_count} checkpoints)...`);
313→
314→  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
315→  if (checkpoints.length === 0) {
316→    console.log(`  No checkpoint commits found, skipping.`);
317→    return { indexed: 0, skipped: 0 };
318→  }
319→
320→  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);
321→
322→  const githubToken = process.env.GITHUB_TOKEN;
323→
324→  // Build text fields (with optional transcript excerpts)
325→  const texts: string[] = [];
326→  let skipped = 0;
327→
328→  for (let i = 0; i < checkpoints.length; i++) {
329→    const cp = checkpoints[i];
330→    let transcriptExcerpt: string | undefined;
331→
332→    if (options.withTranscripts && githubToken) {
333→      transcriptExcerpt =
334→        (await fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken)) ??
335→        undefined;
336→      // Rate limit GitHub API calls
337→      if (i < checkpoints.length - 1) {
338→        await sleep(TRANSCRIPT_DELAY_MS);
339→      }
340→    }
341→
342→    const text = buildSearchText(cp, transcriptExcerpt);
343→    if (!text.trim()) {
344→      skipped++;
345→      texts.push(""); // placeholder to maintain index alignment
346→      continue;
347→    }
348→
349→    texts.push(text);
350→  }
351→
352→  // Filter out empty texts for embedding, but keep index mapping
353→  const nonEmptyIndices = texts.map((t, i) => (t.trim() ? i : -1)).filter((i) => i >= 0);
354→  const nonEmptyTexts = nonEmptyIndices.map((i) => texts[i]);
355→
356→  if (nonEmptyTexts.length === 0) {
357→    console.log(`  All checkpoints had empty text, skipping.`);
358→    return { indexed: 0, skipped };
359→  }
360→
361→  if (options.dryRun) {
362→    console.log(`  [DRY RUN] Would index ${nonEmptyTexts.length} checkpoints.`);
363→    for (let i = 0; i < Math.min(3, nonEmptyTexts.length); i++) {
364→      const idx = nonEmptyIndices[i];
365→      const cp = checkpoints[idx];
366→      console.log(`    - ${cp.checkpoint_id}: ${nonEmptyTexts[i].slice(0, 120)}...`);
367→    }
368→    return { indexed: nonEmptyTexts.length, skipped };
369→  }
370→
371→  // Generate embeddings in batches
372→  console.log(`  Generating embeddings for ${nonEmptyTexts.length} checkpoints...`);
373→  const allEmbeddings: number[][] = [];
374→
375→  for (let i = 0; i < nonEmptyTexts.length; i += EMBEDDING_BATCH_SIZE) {
376→    const batch = nonEmptyTexts.slice(i, i + EMBEDDING_BATCH_SIZE);
377→    const embeddings = await generateEmbeddings(openai, batch);
378→    allEmbeddings.push(...embeddings);
379→
380→    if (i + EMBEDDING_BATCH_SIZE < nonEmptyTexts.length) {
381→      console.log(`    Embedded ${Math.min(i + EMBEDDING_BATCH_SIZE, nonEmptyTexts.length)}/${nonEmptyTexts.length}`);
382→    }
383→  }
384→
385→  // Upsert to Turbopuffer in batches
386→  const ns = tpuf.namespace(`checkpoints-${repo.id}`);
387→  console.log(`  Upserting to Turbopuffer namespace checkpoints-${repo.id}...`);
388→
389→  for (let i = 0; i < nonEmptyIndices.length; i += TURBOPUFFER_UPSERT_BATCH_SIZE) {
390→    const batchIndices = nonEmptyIndices.slice(i, i + TURBOPUFFER_UPSERT_BATCH_SIZE);
391→    const batchEmbeddings = allEmbeddings.slice(i, i + TURBOPUFFER_UPSERT_BATCH_SIZE);
392→
393→    const vectors: Vector[] = batchIndices.map((cpIdx, j) => {
394→      const cp = checkpoints[cpIdx];
395→      const textIdx = nonEmptyIndices.indexOf(cpIdx);
396→
397→      return {
398→        id: i + j + 1, // 1-based auto-incrementing ID within namespace
399→        vector: batchEmbeddings[j],
400→        attributes: {
401→          checkpoint_id: cp.checkpoint_id,
402→          branch: cp.branch,
403→          agent: cp.agent,
404→          author: cp.commit_author_username,
405→          created_at: cp.created_at,
406→          commit_sha: cp.commit_sha,
407→          commit_message: cp.commit_message,
408→          prompt: cp.prompt,
409→          files_touched: cp.files_touched_str,
410→          text: nonEmptyTexts[textIdx],
411→        },
412→      };
413→    });
414→
415→    await ns.upsert({
416→      vectors,
417→      distance_metric: "cosine_distance",
418→    });
419→
420→    if (i + TURBOPUFFER_UPSERT_BATCH_SIZE < nonEmptyIndices.length) {
421→      console.log(`    Upserted ${Math.min(i + TURBOPUFFER_UPSERT_BATCH_SIZE, nonEmptyIndices.length)}/${nonEmptyIndices.length}`);
422→    }
423→  }
424→
425→  const elapsed = ((Date.now() - start) / 1000).toFixed(1);
426→  console.log(`  Done: ${nonEmptyIndices.length} indexed, ${skipped} skipped (${elapsed}s)`);
427→
428→  return { indexed: nonEmptyIndices.length, skipped };
429→}
430→
431→// --- Main ---
432→
433→async function main() {
434→  const options = parseArgs();
435→
436→  // Validate env vars
437→  if (!options.dryRun) {
438→    if (!process.env.TURBOPUFFER_API_KEY) {
439→      console.error("Error: TURBOPUFFER_API_KEY is required (or use --dry-run)");
440→      process.exit(1);
441→    }
442→    if (!process.env.OPENAI_API_KEY) {
443→      console.error("Error: OPENAI_API_KEY is required (or use --dry-run)");
444→      process.exit(1);
445→    }
446→  }
447→
448→  if (options.withTranscripts && !process.env.GITHUB_TOKEN) {
449→    console.error("Error: GITHUB_TOKEN is required when using --with-transcripts");
450→    process.exit(1);
451→  }
452→
453→  const db = createDb();
454→
455→  const tpuf = new Turbopuffer({
456→    apiKey: process.env.TURBOPUFFER_API_KEY ?? "",
457→  });
458→
459→  const openai = new OpenAI({
460→    apiKey: process.env.OPENAI_API_KEY ?? "",
461→  });
462→
463→  console.log("Backfill Search Index");
464→  console.log("=====================");
465→  if (options.dryRun) console.log("[DRY RUN MODE]");
466→  if (options.repo) console.log(`Repo filter: ${options.repo}`);
467→  if (options.limit) console.log(`Limit: ${options.limit} checkpoints per repo`);
468→  if (options.withTranscripts) console.log("Transcript fetching: enabled");
469→
470→  // Fetch repos with checkpoints
471→  let repoQuery = db
472→    .selectFrom("repos")
473→    .select(["id", "full_name", "checkpoint_count"])
474→    .where("checkpoint_count", ">", 0);
475→
476→  if (options.repo) {
477→    repoQuery = repoQuery.where("full_name", "=", options.repo);
478→  }
479→
480→  const repos = (await repoQuery.execute()) as RepoRow[];
481→
482→  if (repos.length === 0) {
483→    console.log("\nNo repos with checkpoints found.");
484→    await db.destroy();
485→    return;
486→  }
487→
488→  console.log(`\nFound ${repos.length} repo(s) with checkpoints.`);
489→
490→  // Process each repo
491→  let totalIndexed = 0;
492→  let totalSkipped = 0;
493→
494→  for (const repo of repos) {
495→    try {
496→      const result = await processRepo(db, tpuf, openai, repo, options);
497→      totalIndexed += result.indexed;
498→      totalSkipped += result.skipped;
499→    } catch (err) {
500→      console.error(`\nError processing ${repo.full_name}:`, err);
501→      console.error("Continuing with next repo...");
502→    }
503→  }
504→
505→  // Summary
506→  console.log("\n=====================");
507→  console.log("Summary:");
508→  console.log(`  Repos processed: ${repos.length}`);
509→  console.log(`  Checkpoints indexed: ${totalIndexed}`);
510→  console.log(`  Checkpoints skipped: ${totalSkipped}`);
511→
512→  await db.destroy();
513→}
514→
515→main();
