 41→interface CliOptions {
 42→  repo: string | null;
 43→  withTranscripts: boolean;
 44→  dryRun: boolean;
 45→  limit: number | null;
 46→}
 47→
 48→function parseArgs(): CliOptions {
 49→  const args = process.argv.slice(2);
 50→  const options: CliOptions = {
 51→    repo: null,
 52→    withTranscripts: false,
 53→    dryRun: false,
 54→    limit: null,
 55→  };
 56→
 57→  for (let i = 0; i < args.length; i++) {
 58→    switch (args[i]) {
 59→      case "--repo":
 60→        options.repo = args[++i];
 61→        if (!options.repo) {
 62→          console.error("Error: --repo requires a value (e.g., 'entireio/cli')");
 63→          process.exit(1);
 64→        }
 65→        break;
 66→      case "--with-transcripts":
 67→        options.withTranscripts = true;
 68→        break;
 69→      case "--dry-run":
 70→        options.dryRun = true;
 71→        break;
 72→      case "--limit":
 73→        options.limit = parseInt(args[++i], 10);
 74→        if (isNaN(options.limit) || options.limit <= 0) {
 75→          console.error("Error: --limit requires a positive integer");
 76→          process.exit(1);
 77→        }
 78→        break;
 79→      default:
 80→        console.error(`Unknown option: ${args[i]}`);
 81→        console.error("Usage: npx tsx scripts/backfill-search.ts [--repo <name>] [--with-transcripts] [--dry-run] [--limit <n>]");
 82→        process.exit(1);
 83→    }
 84→  }
 85→
 86→  return options;
 87→}
