 98→      pool: createPool({
 99→        host: parsed.hostname,
100→        port: Number(parsed.port) || 3306,
101→        user: decodeURIComponent(parsed.username),
102→        password: decodeURIComponent(parsed.password),
103→        database: parsed.pathname.replace("/", ""),
104→        ssl: isLocalhost ? undefined : { rejectUnauthorized: true },
105→      }),
106→    }),
107→  });
108→}
