const CHUNK_SIZE = 50; // process checkpoints in chunks of 50 (fetch transcripts + embed + upsert per chunk)
const CHECKPOINT_BRANCH = "entire/checkpoints/v1";
const GITHUB_API = "https://api.github.com";
const TRANSCRIPT_DELAY_MS = 100; // delay between GitHub API calls to avoid rate limiting
