function formatElapsed(ms: number): string {
  const s = Math.floor(ms / 1000);
  if (s < 60) return `${s}s`;
  const m = Math.floor(s / 60);
  return `${m}m${s % 60}s`;
}

async function processRepo(
  db: Kysely<DB>,
  tpuf: Turbopuffer,
  openai: OpenAI,
  repo: RepoRow,
  options: CliOptions,
): Promise<{ indexed: number; skipped: number }> {
  const start = Date.now();
  const total = repo.checkpoint_count;
  console.log(`\n--- ${repo.full_name} (${total} checkpoints) ---`);

  const checkpoints = await fetchCheckpointsForRepo(db, repo.id, options.limit);
  if (checkpoints.length === 0) {
    console.log(`  No checkpoint commits found, skipping.`);
    return { indexed: 0, skipped: 0 };
  }

  console.log(`  Fetched ${checkpoints.length} checkpoint rows from DB.`);

  const githubToken = process.env.GITHUB_TOKEN;
  const ns = tpuf.namespace(`checkpoints-${repo.id}`);
  let totalIndexed = 0;
  let totalSkipped = 0;
  let totalTranscripts = 0;

  // Process in chunks: for each chunk, fetch transcripts -> build text -> embed -> upsert
  const numChunks = Math.ceil(checkpoints.length / CHUNK_SIZE);

  for (let chunkIdx = 0; chunkIdx < numChunks; chunkIdx++) {
    const chunkStart = chunkIdx * CHUNK_SIZE;
    const chunkEnd = Math.min(chunkStart + CHUNK_SIZE, checkpoints.length);
    const chunk = checkpoints.slice(chunkStart, chunkEnd);
    const chunkNum = chunkIdx + 1;
    const elapsed = formatElapsed(Date.now() - start);

    console.log(`  [${chunkNum}/${numChunks}] Processing checkpoints ${chunkStart + 1}-${chunkEnd} of ${checkpoints.length} (${elapsed})`);

    // 1. Fetch transcripts for this chunk
    const transcripts: (string | undefined)[] = [];
    if (options.withTranscripts && githubToken) {
      let fetched = 0;
      let found = 0;
      for (const cp of chunk) {
        const excerpt = await fetchTranscriptExcerpt(repo.full_name, cp.checkpoint_id, cp.agent, githubToken);
        transcripts.push(excerpt ?? undefined);
        fetched++;
        if (excerpt) found++;
        if (fetched < chunk.length) {
          await sleep(TRANSCRIPT_DELAY_MS);
        }
      }
      totalTranscripts += found;
      console.log(`    Transcripts: ${found}/${chunk.length} found`);
    } else {
      chunk.forEach(() => transcripts.push(undefined));
    }

    // 2. Build search text for each checkpoint
    const texts: string[] = [];
    const validIndices: number[] = []; // indices within this chunk that have non-empty text
    let chunkSkipped = 0;

    for (let i = 0; i < chunk.length; i++) {
      const text = buildSearchText(chunk[i], transcripts[i]);
      if (!text.trim()) {
        chunkSkipped++;
        continue;
      }
      texts.push(text);
      validIndices.push(i);
    }

    totalSkipped += chunkSkipped;

    if (texts.length === 0) {
      console.log(`    All empty, skipped.`);
      continue;
    }

    if (options.dryRun) {
      console.log(`    [DRY RUN] Would index ${texts.length} (${chunkSkipped} skipped)`);
      totalIndexed += texts.length;
      continue;
    }

    // 3. Generate embeddings
    const embeddings = await generateEmbeddings(openai, texts);
