1236→// Get checkpoints for a specific repo
1237→// ALWAYS serves from D1 - background sync populates the data
1238→// Pass ?source=github to trigger a sync from GitHub before returning data (for local dev)
1239→repoRoutes.get("/:org/:repo/checkpoints", optionalAuth, rateLimitUnauthenticated, async (c) => {
1240→  const userId = c.get("userId") as string | undefined;
1241→
1242→  const org = c.req.param("org");
1243→  const repo = c.req.param("repo");
1244→  const repoFullName = `${org}/${repo}`;
1245→
1246→  // Optional query params
1247→  const branch = c.req.query("branch") || "main";
1248→  const limitParam = c.req.query("limit");
1249→  const limit = limitParam ? parseInt(limitParam, 10) : 100;
1250→  const source = c.req.query("source"); // "github" to trigger sync
1251→
1252→  // Validate branch name format to prevent cache key issues and unexpected behavior
1253→  if (!isValidBranchName(branch)) {
1254→    return c.json({ error: "Invalid branch name format" }, 400);
1255→  }
1256→
1257→  try {
1258→    const db = getDb(c.env);
1259→    let repoRecord: Repo | null = null;
1260→
1261→    // Helper to get GitHub token only when needed (for source=github or branch validation)
1262→    // Uses undefined as "not yet fetched" so null can be cached as "fetched, no token"
1263→    let cachedToken: string | null | undefined = undefined;
1264→    const getGitHubToken = async (): Promise<string | null> => {
1265→      if (cachedToken !== undefined) return cachedToken;
1266→      const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoRecord);
1267→      if (tokenResult.response) {
1268→        const err = new Error("User not found");
1269→        (err as any).status = 404;
1270→        throw err;
1271→      }
1272→      cachedToken = tokenResult.token;
1273→      return tokenResult.token;
1274→    };
1275→
1276→    // For source=github (local dev), use multi-query path since we may need to create/sync.
1277→    // For normal requests, resolve repo access first, then fetch branch checkpoints separately.
1278→    // This avoids false 404s when a repo exists but has zero checkpoints on the branch.
1279→    let dbCheckpoints: CheckpointWithCommit[] = [];
1280→
1281→    if (source === "github" && isLocalDev(c.env)) {
1282→      // Local dev path: requires auth (webhooks don't fire in local dev)
1283→      if (!userId) return c.json({ error: "Authentication required" }, 401);
1284→
1285→      // Also invalidate branches cache since webhooks don't fire in local dev
1286→      await c.env.ENTIRE_CACHE.delete(`branches:${repoFullName}`);
1287→      console.log(`source=github: invalidated branches cache for ${repoFullName}`);
1288→
1289→      const result = await fetchRepoWithSyncForLocalDev(
1290→        db,
1291→        repoFullName,
1292→        userId,
1293→        branch,
1294→        limit,
1295→        getGitHubToken,
1296→      );
1297→      if (result instanceof Response) return result;
1298→      repoRecord = result.repoRecord;
1299→      dbCheckpoints = result.checkpoints;
1300→    } else {
1301→      const repoAccess = await checkRepoAccess(
1302→        db,
1303→        repoFullName,
1304→        userId,
1305→        { requireRepo: true },
1306→      );
1307→      if (repoAccess instanceof Response) return repoAccess;
1308→
1309→      repoRecord = repoAccess;
1310→      dbCheckpoints = await db.checkpoints.getForBranch(repoRecord.id, branch, { limit });
1311→    }
1312→
1313→    // null = unknown (repo not in DB), true/false = definitive from DB
1314→    const appHasAccess = repoRecord ? repoRecord.app_has_access : null;
1315→
1316→    // Validate branch existence when we have no checkpoints
1317→    // This catches non-existent branches even if repo hasn't been synced yet
1318→    if (dbCheckpoints.length === 0) {
1319→      // If repo exists in DB, check if it has any commits for this branch
1320→      const hasCommitsInDb = repoRecord
1321→        ? await db.checkpoints.branchHasCommits(repoRecord.id, branch)
1322→        : false;
1323→
1324→      if (!hasCommitsInDb) {
1325→        // If app doesn't have access, skip branch check and show "no access" state
1326→        // (User's token might also not have access, giving false 404s)
1327→        if (appHasAccess !== false) {
1328→          // No commits in DB - verify with GitHub API (only fetches token if needed)
1329→          const token = await getGitHubToken();
1330→          const branchExists = await checkBranchExists(
1331→            repoFullName,
1332→            branch,
1333→            token,
1334→          );
1335→
1336→          // If GitHub definitively says branch doesn't exist, return 404
1337→          if (branchExists === false) {
1338→            return c.json({ error: `Branch '${branch}' not found` }, 404);
1339→          }
1340→          // If branchExists is true or null, continue - let component show appropriate empty state
1341→        }
1342→        // If appHasAccess === false, skip branch check and return empty checkpoints
1343→      }
1344→    }
1345→
1346→    // Build response from DB data
1347→    const checkpoints: CheckpointInfo[] = dbCheckpoints.map(mapCheckpointToInfo);
1348→
1349→    // session_branch_exists is true if repo has been backfilled (branch was checked during sync)
1350→    // null if we haven't checked yet (repo not synced)
1351→    const sessionBranchExists = repoRecord?.checkpoints_backfilled_at
1352→      ? true
1353→      : null;
1354→
1355→    return c.json({
1356→      checkpoints,
1357→      repo_full_name: repoFullName,
1358→      updated_at: new Date().toISOString(),
1359→      source: "db",
1360→      app_has_access: appHasAccess,
1361→      session_branch_exists: sessionBranchExists,
1362→    });
1363→  } catch (err) {
1364→    if ((err as any)?.status === 404) {
1365→      return c.json({ error: (err as Error).message }, 404);
1366→    }
1367→    if (isGitHubAuthError(err)) {
1368→      return c.json({ error: "GitHub token expired" }, 401);
1369→    }
1370→    console.error(`Failed to fetch checkpoints for ${repoFullName}:`, err);
1371→    recordSpanError(err);
1372→    return c.json({ error: "Failed to fetch checkpoints" }, 500);
1373→  }
1374→});
