 99→  WEBHOOK_QUEUE: Queue;           // Webhook retry queue
100→  REPO_SYNC_QUEUE: Queue;         // Repo checkpoint sync queue
101→  USER_REPO_SYNC_QUEUE: Queue;    // User repo sync queue (for stale/failed syncs)
102→
103→  // Environment variables
104→  ENVIRONMENT: string; // e.g., "development", "staging", "production"
105→  FRONTEND_BASE_URL: string; // Used for redirects/CORS
106→  API_BASE_URL?: string; // If set, used for OAuth redirect URIs; defaults to request origin
107→
108→  // Secrets (set via wrangler secret put)
109→  GITHUB_CLIENT_ID: string;
110→  GITHUB_CLIENT_SECRET: string;
111→  GITHUB_APP_NAME: string; // GitHub App slug (e.g., "my-app-name")
112→  GITHUB_APP_PRIVATE_KEY: string; // GitHub App private key (PEM format)
113→  ENCRYPTION_KEY: string;
114→  SESSION_SECRET: string;
115→  GITHUB_WEBHOOK_SECRET: string;
116→
117→  // OpenTelemetry (optional)
118→  OTEL_EXPORTER_OTLP_ENDPOINT?: string; // e.g., https://api.honeycomb.io
119→  OTEL_EXPORTER_OTLP_HEADERS?: string;  // e.g., x-honeycomb-team=your-api-key
120→}
121→
122→// Variables stored in Hono context
123→export interface Variables {
124→  userId: string;
125→}
126→
127→// Hono context with bindings
128→import type { Context } from "hono";
129→
130→export type AppContext = Context<{ Bindings: Env; Variables: Variables }>;
131→

  1→function getApiBaseUrl(): string {
  2→  if (import.meta.env.VITE_API_BASE_URL) {
  3→    return import.meta.env.VITE_API_BASE_URL;
  4→  }
  5→  // In development, use the same hostname as the current page to support local network access
  6→  if (import.meta.env.DEV && typeof window !== "undefined") {
  7→    return `http://${window.location.hostname}:8787`;
  8→  }
  9→  return "https://entire.io";
 10→}
 11→
 12→const API_BASE_URL = getApiBaseUrl();
 13→
 14→type RequestOptions = RequestInit & { token?: string };
 15→
 16→export class ApiError extends Error {
 17→  status: number;
 18→  constructor(message: string, status: number) {
 19→    super(message);
 20→    this.name = "ApiError";
 21→    this.status = status;
 22→  }
 23→}
 24→
 25→// Read a cookie value by name
 26→export function getCookie(name: string): string | null {
 27→  const match = document.cookie.match(new RegExp(`(^|; )${name}=([^;]*)`));
 28→  return match ? match[2] : null;
 29→}
 30→
 31→/**
 32→ * Check if an error indicates the user needs to re-authenticate with GitHub.
 33→ * Used to show appropriate UI when GitHub OAuth tokens have expired.
 34→ *
 35→ * Matches specific API error messages that indicate auth issues:
 36→ * - "Not authenticated" (401) - no session
 37→ * - "Session expired" (401) - session timed out
 38→ * - "GitHub token required for this operation" (403) - token missing/invalid
 39→ * - "GitHub token expired" (401) - GitHub rejected the token (e.g. after concurrent refresh)
 40→ */
 41→export function isAuthError(error: Error | null | undefined): boolean {
 42→  if (!error) return false;
 43→  const message = error.message.toLowerCase();
 44→  return (
 45→    message === "not authenticated" ||
 46→    message === "session expired" ||
 47→    message === "github token required for this operation" ||
 48→    message === "github token expired"
 49→  );
 50→}
 51→
 52→export function normalizeErrorMessage(data: unknown, fallback: string): string {
 53→  if (data && typeof data === "object") {
 54→    if (
 55→      "error" in data &&
 56→      typeof (data as { error?: unknown }).error === "string"
 57→    ) {
 58→      return (data as { error: string }).error;
 59→    }
 60→
 61→    if (
 62→      "errors" in data &&
 63→      Array.isArray((data as { errors?: unknown }).errors)
 64→    ) {
 65→      const errors = (data as { errors: unknown[] }).errors.filter(
 66→        (message): message is string => typeof message === "string",
 67→      );
 68→
 69→      if (errors.length > 0) {
 70→        return errors.join(", ");
 71→      }
 72→    }
 73→  }
 74→
 75→  return fallback;
 76→}
 77→
 78→export async function request<T>(
 79→  endpoint: string,
 80→  options: RequestOptions = {},
 81→): Promise<T> {
 82→  const { token: _token, headers, ...rest } = options;
 83→  const requestHeaders = new Headers(headers ?? {});
 84→
 85→  if (rest.body && !requestHeaders.has("Content-Type")) {
 86→    requestHeaders.set("Content-Type", "application/json");
 87→  }
 88→
 89→  // Add CSRF token header for state-changing requests (double-submit cookie pattern)
 90→  const method = (rest.method ?? "GET").toUpperCase();
 91→  if (["POST", "PUT", "DELETE", "PATCH"].includes(method)) {
 92→    const csrfToken = getCookie("csrf");
 93→    if (csrfToken) {
 94→      requestHeaders.set("X-CSRF-Token", csrfToken);
 95→    }
 96→  }
 97→
 98→  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
 99→    ...rest,
100→    headers: requestHeaders,
101→    credentials: "include",
102→  });
103→
104→  let data: unknown = null;
105→  const contentType = response.headers.get("Content-Type") ?? "";
106→
107→  if (contentType.includes("application/json")) {
108→    data = await response.json().catch(() => null);
109→  }
110→
111→  if (!response.ok) {
112→    const message = normalizeErrorMessage(
113→      data,
114→      response.statusText || "Request failed",
115→    );
116→    throw new ApiError(message, response.status);
117→  }
118→
119→  return data as T;
120→}
